import type { DocumentNode } from '@apollo/client/core'
import { TokenRefreshLink } from 'apollo-link-token-refresh'
import type { OperationDefinitionNode } from 'graphql'
import { type JwtPayload, jwtDecode } from 'jwt-decode'
import { API_URL } from '@/constants'
import { useAuthStore } from '@/stores/authStore'
import { router } from 'expo-router'

function getMutationName(doc: DocumentNode): string | undefined {
	const mutation = doc.definitions.find(
		(def): def is OperationDefinitionNode =>
			def.kind === 'OperationDefinition' && def.operation === 'mutation'
	)

	const selection = mutation?.selectionSet.selections[0]
	if (selection?.kind === 'Field') {
		return selection.name.value
	}

	return undefined
}
const WHITELISTED_MUTATIONS = [
	'requestMagicLink',
	'signUpWithMagicLinkOrRequestMagicLink',
	'signInWithMagicLinkCode'
]
export const tokenRefreshLink = new TokenRefreshLink<{
	accessToken: string
	refreshToken: string
} | null>({
	accessTokenField: 'payload',
	isTokenValidOrUndefined: async (operation) => {
		const operationName = getMutationName(operation.query)
		// these do not need valid tokens
		if (operationName && WHITELISTED_MUTATIONS.includes(operationName)) {
			return true
		}
		const token = useAuthStore.getState().auth?.accessToken

		if (!token) {
			return true
		}

		const claims: JwtPayload = jwtDecode(token)

		if (!claims.exp) return true

		const expirationTimeInSeconds = claims.exp * 1000
		const now = new Date()
		const isValid = expirationTimeInSeconds >= now.getTime()

		return isValid
	},
	fetchAccessToken: async () => {
		const headers = new Headers()
		headers.append('Content-Type', 'application/json')
		const refreshToken = useAuthStore.getState().auth?.refreshToken
		if (refreshToken) {
			headers.append('x-anything-refresh-token', refreshToken)
		}
		const response = await fetch(`${API_URL}/refresh_token`, {
			method: 'POST',
			headers
		})

		if (!response.ok) {
			throw new Error('Failed to refresh token')
		}
		return response.json()
	},
	handleError: () => {
		useAuthStore.getState().setAuth(null)
		router.replace('/')
	},
	handleFetch: (auth) => {
		useAuthStore.getState().setAuth(auth)
	},

	handleResponse:
		(_operation, _accessTokenField) =>
		(response: { accessToken: string; refreshToken: string; ok: boolean }) => {
			if (response.ok) {
				return {
					payload: {
						accessToken: response.accessToken,
						refreshToken: response.refreshToken
					}
				}
			}
			return { payload: null }
		}
})
